tool.command:
set -o pipefail;
mkdir -p '$out_file.extra_files_path/taxonomy/' && wget -O - '$taxonomy_url' | tar -xz -C '$out_file.extra_files_path/taxonomy/' && if [[ ! -f '$out_file.extra_files_path/taxonomy/nodes.dmp' ]]; then >&2 echo "nodes.dmp missing"; exit 1; fi &&
#if $name_maps mkdir -p '$out_file.extra_files_path/accession2taxid/' && #if $partial_data #set files = ['pdb.accession2taxid'] #else #set files = ['dead_nucl.accession2taxid', 'dead_prot.accession2taxid', 'dead_wgs.accession2taxid', 'nucl_gb.accession2taxid', 'nucl_wgs.accession2taxid', 'pdb.accession2taxid', 'prot.accession2taxid', 'prot.accession2taxid.FULL'] #end if #for file in files wget -O - ftp://ftp.ncbi.nlm.nih.gov/pub/taxonomy/accession2taxid/${file}.gz | gunzip -c > '$out_file.extra_files_path/accession2taxid/${file}' && #end for #end if #if str($database_name) mv '$dmjson' '$out_file' #else taxonomy_digest=\$( cd '$out_file.extra_files_path/taxonomy/' && find . -type f -exec sha256sum '{}' + | LC_ALL=C sort | sha256sum ) && taxonomy_digest="\${taxonomy_digest%% *}" && taxonomy_digest_short="\${taxonomy_digest:0:12}" && #if $name_maps accession_digest=\$( cd '$out_file.extra_files_path/accession2taxid/' && find . -type f -exec sha256sum '{}' + | LC_ALL=C sort | sha256sum ) && accession_digest="\${accession_digest%% *}" && accession_digest_short="\${accession_digest:0:12}" && #end if sed -e "s/__NCBI_TAXONOMY_SHA256__/\$taxonomy_digest/g" -e "s/__NCBI_TAXONOMY_SHA256_SHORT__/\$taxonomy_digest_short/g" #if $name_maps -e "s/__NCBI_ACCESSION2TAXID_SHA256__/\$accession_digest/g" -e "s/__NCBI_ACCESSION2TAXID_SHA256_SHORT__/\$accession_digest_short/g" #end if '$dmjson' > '$out_file' #end if
